package io.github.jesterportfolio.hearth.economy;

import java.util.*;import java.util.concurrent.*;import java.sql.*;
import io.github.jesterportfolio.hearth.persistence.*;

/** 보관은 데이터 삭제가 아니다. ID·원본 행은 유지하고 hot 조회/상한만 분리한다. */
public final class PlatformArchiveStore {
    public record Config(PlatformStore.Config value,boolean archived){}
    public record Vault(UUID id,UUID world,String key,String seal,String state,long revision){}
    private final PostgresProgressStore db;private final EconomyStore economy;private final UUID realm;
    public PlatformArchiveStore(PostgresProgressStore db,EconomyStore economy,UUID realm){this.db=db;this.economy=economy;this.realm=realm;}
    @FunctionalInterface private interface Work<T>{T run(Connection c)throws Exception;}
    private <T>CompletionStage<T> tx(String name,Work<T> work){return db.module(name,c->{c.setAutoCommit(false);try{economy.housingLock(c,economy.context(realm,new UUID(0,0)));T result=work.run(c);c.commit();return result;}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}});}
    private static void require(boolean value){if(!value)throw new IllegalStateException("ARCHIVE_CAS_OR_SCOPE");}
    public CompletionStage<Config> config(UUID id){return tx("archive_config_inspect",c->{try(var s=c.prepareStatement("SELECT * FROM hearth_economy.platform_config_change WHERE realm_id=? AND request_id=?")){s.setObject(1,realm);s.setObject(2,id);try(var r=s.executeQuery()){require(r.next());return new Config(new PlatformStore.Config(id,r.getString("name"),r.getString("before_hash"),r.getString("after_hash"),r.getString("state")),r.getBoolean("archived"));}}});}
    public CompletionStage<Void> config(Config expected){return tx("archive_config",c->{var e=expected.value;require(Set.of("COMMITTED","ROLLED_BACK").contains(e.state()));try(var s=c.prepareStatement("UPDATE hearth_economy.platform_config_change SET archived=true WHERE realm_id=? AND request_id=? AND name=? AND before_hash=? AND after_hash=? AND state=? AND archived=?")){s.setObject(1,realm);s.setObject(2,e.request());s.setString(3,e.name());s.setString(4,e.before());s.setString(5,e.after());s.setString(6,e.state());s.setBoolean(7,expected.archived);require(s.executeUpdate()==1);}return null;});}
    public CompletionStage<Void> job(JobStore.Job expected){return tx("archive_job",c->{require(Set.of(JobStore.State.SUCCEEDED,JobStore.State.CANCELLED).contains(expected.state()));try(var s=c.prepareStatement("UPDATE hearth_economy.platform_job SET archived=true WHERE realm_id=? AND request_id=? AND state=? AND revision=? AND kind=? AND target=? AND started_tick=?")){s.setObject(1,realm);s.setObject(2,expected.id());s.setString(3,expected.state().name());s.setLong(4,expected.revision());s.setString(5,expected.kind());s.setString(6,expected.target());s.setLong(7,expected.tick());require(s.executeUpdate()==1);}return null;});}
    public CompletionStage<List<String>> history(String kind,int offset){if(!Set.of("config","job").contains(kind)||offset<0||offset>1_000_000)throw new IllegalArgumentException("ARCHIVE_PAGE");return tx("archive_history",c->{var out=new ArrayList<String>();String table=kind.equals("config")?"platform_config_change":"platform_job";try(var s=c.prepareStatement("SELECT request_id,state FROM hearth_economy."+table+" WHERE realm_id=? AND archived ORDER BY created_at DESC,request_id LIMIT 36 OFFSET ?")){s.setObject(1,realm);s.setInt(2,offset);try(var r=s.executeQuery()){while(r.next())out.add(r.getObject(1)+" "+r.getString(2));}}return List.copyOf(out);});}
    private Vault vault(ResultSet r)throws Exception{return new Vault(r.getObject("request_id",UUID.class),r.getObject("world_uuid",UUID.class),r.getString("world_key"),r.getString("seal"),r.getString("state"),r.getLong("revision"));}
    public CompletionStage<Optional<Vault>> vault(UUID id){return tx("archive_world_by_id",c->{try(var s=c.prepareStatement("SELECT * FROM hearth_economy.resource_archive WHERE realm_id=? AND request_id=?")){s.setObject(1,realm);s.setObject(2,id);try(var r=s.executeQuery()){return r.next()?Optional.of(vault(r)):Optional.empty();}}});}
    public CompletionStage<List<Vault>> vaults(){return tx("archive_worlds",c->{var out=new ArrayList<Vault>();try(var s=c.prepareStatement("SELECT * FROM hearth_economy.resource_archive WHERE realm_id=? ORDER BY CASE WHEN state IN ('PREPARED','RESTORING') THEN 0 ELSE 1 END,request_id LIMIT 128")){s.setObject(1,realm);try(var r=s.executeQuery()){while(r.next()){require(out.size()<4096);out.add(vault(r));}}}return List.copyOf(out);});}
    public CompletionStage<Vault> prepare(PlatformStore.Reset row,String seal){return tx("archive_world_prepare",c->{require(row.phase().equals("RETIRED")&&row.world()!=null&&row.key().startsWith("hearth_resource:r_"));
        try(var s=c.prepareStatement("SELECT * FROM hearth_economy.resource_reset WHERE realm_id=? AND request_id=? AND phase='RETIRED' AND new_uuid=? AND new_key=? AND NOT EXISTS(SELECT 1 FROM hearth_economy.resource_reset WHERE realm_id=? AND phase IN ('ACTIVE','PREPARING','READY') AND (new_uuid=? OR old_uuid=?)) AND NOT EXISTS(SELECT 1 FROM hearth_economy.platform_job WHERE realm_id=? AND state IN ('RUNNING','HOLD'))")){s.setObject(1,realm);s.setObject(2,row.request());s.setObject(3,row.world());s.setString(4,row.key());s.setObject(5,realm);s.setObject(6,row.world());s.setObject(7,row.world());s.setObject(8,realm);try(var r=s.executeQuery()){require(r.next());}}
        try(var q=c.prepareStatement("SELECT * FROM hearth_economy.resource_archive WHERE realm_id=? AND request_id=?")){q.setObject(1,realm);q.setObject(2,row.request());try(var r=q.executeQuery()){if(r.next()){var old=vault(r);require(old.world.equals(row.world())&&old.key.equals(row.key())&&old.seal.equals(seal)&&!old.state.equals("RESTORING"));return old;}}}
        require(seal.matches("[a-f0-9]{64}"));try(var s=c.prepareStatement("INSERT INTO hearth_economy.resource_archive VALUES(?,?,?,?,?,'PREPARED',0)")){s.setObject(1,realm);s.setObject(2,row.request());s.setObject(3,row.world());s.setString(4,row.key());s.setString(5,seal);s.executeUpdate();}return new Vault(row.request(),row.world(),row.key(),seal,"PREPARED",0);
    });}
    public CompletionStage<Vault> transition(Vault row,String next){return tx("archive_world_state",c->{require(row.state.equals("PREPARED")&&next.equals("STORED")||row.state.equals("STORED")&&next.equals("RESTORING")||row.state.equals("RESTORING")&&next.equals("RESTORED")||row.state.equals("RESTORED")&&next.equals("PREPARED"));try(var s=c.prepareStatement("UPDATE hearth_economy.resource_archive SET state=?,revision=revision+1 WHERE realm_id=? AND request_id=? AND state=? AND revision=? AND world_uuid=? AND world_key=? AND seal=? RETURNING *")){s.setString(1,next);s.setObject(2,realm);s.setObject(3,row.id);s.setString(4,row.state);s.setLong(5,row.revision);s.setObject(6,row.world);s.setString(7,row.key);s.setString(8,row.seal);try(var r=s.executeQuery()){require(r.next());return vault(r);}}});}
}
